# CX file-ownership map (planset citrate-core-social, 02_ARCHITECTURE §3.3).
# Each lane owns a disjoint set of files. `cx-ownership-check.sh <lane>` fails a branch whose
# diff touches a file outside its lane's set — the mechanical guarantee against races to main
# (01_SCOPE §5.1). Format: one line per allowed glob:  <lane> <glob>
# Globs are shell patterns matched against repo-relative paths. `**` = any depth.
#
# ALWAYS-ALLOWED (any lane): its own sprint file + the planset are process artifacts, not code.
* .agentile/sprints/active/**
* .agentile/cx-ownership.map

# --- s0: the scaffold. The ONLY lane permitted to touch the shared spine (01 §4.1). ---
s0 src/bridge/**
s0 src/shell/**
s0 src/surfaces/**
s0 src/App.tsx
s0 src-tauri/src/**
s0 src-tauri/tauri.bundle-node.conf.json
s0 src-tauri/tauri.local-run.conf.json
s0 src-tauri/binaries/README.md
s0 scripts/**
s0 .agentile/**
s0 kit/src/**

# --- s1: models (Lane A). Owns the model/inference/oauth host files + its slice/surface. ---
s1 src-tauri/src/model.rs
s1 src-tauri/src/model_catalog.rs
s1 src-tauri/src/serve.rs
s1 src-tauri/src/ai.rs
s1 src-tauri/src/connections.rs
s1 src-tauri/src/oidc.rs
s1 src-tauri/src/model_tests.rs
s1 src-tauri/src/model_catalog_tests.rs
s1 src-tauri/src/serve_tests.rs
s1 src-tauri/src/connections_tests.rs
s1 src-tauri/src/oidc_tests.rs
# oidc lives in the shared kit, not src-tauri (map corrected in CX-S1.2). The GitHub Accept
# fix touches it; no other lane owns it, so granting to s1 creates no cross-lane race.
s1 kit/src/oidc.rs
s1 kit/src/oidc_tests.rs
s1 src/bridge/tauri/models.ts
s1 src/bridge/sim/models.ts
s1 src/bridge/contracts/models.contract.test.ts
s1 src/shell/slices/models.ts
s1 src/surfaces/Models.tsx

